import{clamp,order,advance,recognize,validState}from'./core.js';
const $=s=>document.querySelector(s),uid=()=>crypto.randomUUID(),KEY='initiative.encounter.v1',NS='http://www.w3.org/2000/svg';
const demo=()=>({version:1,title:'Überfall am alten Wachturm',demo:true,started:true,round:1,active:'lyra',people:[{id:'lyra',name:'Lyra',kind:'ally',hp:32,max:38,init:19,x:375,y:475},{id:'g1',name:'Goblin-Späher 1',kind:'enemy',hp:7,max:12,init:16,x:575,y:325},{id:'g2',name:'Goblin-Späher 2',kind:'enemy',hp:12,max:12,init:16,x:625,y:375},{id:'thorin',name:'Thorin',kind:'ally',hp:45,max:45,init:12,x:475,y:525}],shapes:[{id:'room',type:'rect',x:250,y:200,w:500,h:350},{id:'tower',type:'ellipse',x:600,y:100,w:200,h:200},{id:'wall1',type:'wall',points:[{x:250,y:350},{x:350,y:350}]},{id:'wall2',type:'wall',points:[{x:500,y:200},{x:500,y:300}]},{id:'pillar',type:'rect',x:400,y:300,w:50,h:50}]});
let state=demo(),history=[],tool='select',snap=true,editId=null,gesture=null,toastTimer,storageBroken=false;
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(validState(parsed))state=parsed;else throw Error('invalid');}}catch{storageBroken=true;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function checkpoint(){history.push(structuredClone(state));if(history.length>60)history.shift();}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(state));storageBroken=false;$('#save-status').innerHTML='<span></span> Lokal gespeichert';}catch{storageBroken=true;$('#save-status').textContent='Speichern nicht möglich · bitte sichern';}}
function mutate(fn){checkpoint();fn();persist();render();}
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=s=>s.trim().split(/\s+/).map(t=>t[0]).slice(0,2).join('').toUpperCase();
function render(){const sorted=order(state.people);$('#encounter-title').value=state.title;$('#participant-count').textContent=`${state.people.filter(p=>p.kind==='ally').length} Helden · ${state.people.filter(p=>p.kind==='enemy').length} Gegner`;$('#list-count').textContent=state.people.length;$('#round').textContent=state.round;$('#demo-label').hidden=!state.demo;$('#undo').disabled=!history.length;$('#next-turn').disabled=!state.people.length;$('#roll-all').disabled=!state.people.length;const active=state.people.find(p=>p.id===state.active);$('#turn-hint').textContent=active?`${active.name} ist am Zug`:'Füge Beteiligte hinzu, um zu starten.';
$('#combatant-list').innerHTML=sorted.length?sorted.map(p=>`<article class="combatant ${p.id===state.active?'active':''} ${p.hp===0?'downed':''}" data-person="${escape(p.id)}">${p.id===state.active?'<div class="active-label"><span>JETZT AM ZUG</span><span>◆</span></div>':''}<div class="combatant-top"><div class="initiative-number"><strong>${p.init}</strong><small>INIT</small></div><div class="avatar ${p.kind}">${escape(initials(p.name))}</div><div class="person-details"><div class="person-name">${escape(p.name)}</div><div class="person-kind">${p.kind==='ally'?'Held':'Gegner'}${p.hp===0?' · 0 HP':''}</div></div><button class="edit-person" data-action="edit" title="${escape(p.name)} bearbeiten" aria-label="${escape(p.name)} bearbeiten">···</button></div><div class="hp-row"><div class="hp-track"><div class="hp-fill ${p.hp/p.max<.4?'low':''}" style="width:${p.hp/p.max*100}%"></div></div><div class="hp-number">${p.hp} <small>/ ${p.max} HP</small></div></div><div class="hp-controls"><span>TREFFERPUNKTE</span><button data-action="damage" class="damage" title="Schaden zufügen" aria-label="${escape(p.name)} Schaden zufügen">−</button><input aria-label="HP-Betrag für ${escape(p.name)}" type="number" min="1" max="9999" value="1"><button data-action="heal" title="Heilen" aria-label="${escape(p.name)} heilen">＋</button></div></article>`).join(''):'<div class="empty-list"><strong>Noch ist alles ruhig.</strong>Füge Helden und Gegner hinzu.<br>Die Initiative sortiert sich von selbst.<button class="secondary" id="empty-add">＋ Beteiligte hinzufügen</button></div>';$('#empty-add')?.addEventListener('click',()=>openParticipant());renderMap();}
function svgEl(tag,attrs={}){const el=document.createElementNS(NS,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));return el;}
function makeShape(sh,isDraft=false){let el;const attrs={fill:'none',stroke:isDraft?'#8d9e70':'#7b806a','stroke-width':isDraft?3:5,'stroke-linecap':'round','stroke-linejoin':'round'};if(sh.type==='rect'){el=svgEl('rect',{x:sh.x,y:sh.y,width:sh.w,height:sh.h,rx:3,...attrs,fill:isDraft?'#b9c79d33':'url(#floor)'});}else if(sh.type==='ellipse'){el=svgEl('ellipse',{cx:sh.x+sh.w/2,cy:sh.y+sh.h/2,rx:sh.w/2,ry:sh.h/2,...attrs,fill:isDraft?'#b9c79d33':'url(#floor)'});}else{el=svgEl('polyline',{points:sh.points.map(p=>`${p.x},${p.y}`).join(' '),...attrs});}if(isDraft)el.setAttribute('stroke-dasharray','7 5');else{el.dataset.shape=sh.id;el.style.pointerEvents='all';if(tool==='erase')el.style.cursor='pointer';}return el;}
function renderMap(){const shapes=$('#shapes'),tokens=$('#tokens');shapes.replaceChildren(...state.shapes.map(s=>makeShape(s)));tokens.replaceChildren();for(const p of state.people){const g=svgEl('g',{'data-token':p.id,transform:`translate(${p.x} ${p.y})`,tabindex:0,role:'button','aria-label':`${p.name}, ${p.hp} von ${p.max} HP. Pfeiltasten zum Verschieben.`,opacity:p.hp===0?.5:1});let active=p.id===state.active;if(active)g.append(svgEl('circle',{r:28,fill:'none',stroke:'#bd9d58','stroke-width':2.5,'stroke-dasharray':'4 4'}));g.append(svgEl('circle',{r:22,fill:p.kind==='ally'?'#55755d':'#ad7865',stroke:'#fffdf0','stroke-width':3,filter:'url(#shadow)'}));const text=svgEl('text',{'text-anchor':'middle','dominant-baseline':'central',fill:'#fffbed','font-family':'Manrope,system-ui','font-size':13,'font-weight':750,'pointer-events':'none'});text.textContent=initials(p.name);g.append(text);const name=svgEl('text',{y:40,'text-anchor':'middle',fill:'#606d54','font-size':10,'font-weight':600,'paint-order':'stroke',stroke:'#eeebdf','stroke-width':4,'pointer-events':'none'});name.textContent=p.name;g.append(name);tokens.append(g);}$('#map-empty').hidden=!!(state.people.length||state.shapes.length);}
function openParticipant(id=null){editId=id;let p=state.people.find(p=>p.id===id);$('#participant-form').reset();$('#dialog-title').textContent=p?'Beteiligten bearbeiten':'Wer zieht in den Kampf?';$('#p-name').value=p?.name??'';$('#p-hp').value=p?.max??12;$('#p-init').value=p?.init??10;document.querySelector(`input[name="kind"][value="${p?.kind??'enemy'}"]`).checked=true;$('#quantity-label').hidden=!!p;$('#submit-participant').textContent=p?'Änderungen speichern':'Zum Kampf hinzufügen ＋';$('#remove-person')?.remove();if(p){let b=document.createElement('button');b.type='button';b.className='text-button';b.id='remove-person';b.textContent='Aus dem Kampf entfernen';b.style.marginTop='15px';b.onclick=()=>{mutate(()=>{state.people=state.people.filter(x=>x.id!==id);if(state.active===id)state.active=order(state.people)[0]?.id??null;});$('#participant-dialog').close();toast('Entfernt. Mit „Rückgängig“ wiederherstellen.');};$('#participant-form').append(b);}$('#participant-dialog').showModal();$('#p-name').focus();}
$('#participant-form').onsubmit=e=>{e.preventDefault();let name=$('#p-name').value.trim();if(!name){$('#p-name').setCustomValidity('Bitte einen Namen eingeben.');$('#p-name').reportValidity();return;}let max=+$('#p-hp').value,init=+$('#p-init').value,count=editId?1:+$('#p-count').value,kind=document.querySelector('input[name=kind]:checked').value;if(state.people.length+(!editId?count:0)>100){toast('Maximal 100 Beteiligte pro Kampf.');return;}mutate(()=>{if(editId){let p=state.people.find(p=>p.id===editId);Object.assign(p,{name,kind,max,hp:Math.min(p.hp,max),init});if(state.started===false)state.active=order(state.people)[0]?.id??null;}else{for(let i=0;i<count;i++){const n=state.people.length;state.people.push({id:uid(),name:count>1?`${name.slice(0,46)} ${i+1}`:name,kind,max,hp:max,init,x:75+(n%18)*50,y:75+(Math.floor(n/18)%12)*50});}if(!state.active||state.started===false)state.active=order(state.people)[0].id;}state.demo=false;});$('#participant-dialog').close();toast(editId?'Änderungen gespeichert.':`${count===1?name:count+' Beteiligte'} hinzugefügt.`);};$('#p-name').oninput=()=>$('#p-name').setCustomValidity('');$('#roll-one').onclick=()=>$('#p-init').value=1+Math.floor(Math.random()*20);$('#add').onclick=()=>openParticipant();
$('#combatant-list').onclick=e=>{let b=e.target.closest('[data-action]');if(!b)return;let card=b.closest('[data-person]'),p=state.people.find(p=>p.id===card.dataset.person);if(b.dataset.action==='edit'){openParticipant(p.id);return;}let amount=+card.querySelector('input').value;if(!Number.isInteger(amount)||amount<1||amount>9999){toast('Bitte einen HP-Betrag von 1 bis 9999 eingeben.');return;}mutate(()=>p.hp=clamp(p.hp+(b.dataset.action==='heal'?amount:-amount),0,p.max));toast(`${p.name}: ${p.hp} / ${p.max} HP`);};
$('#encounter-title').onchange=e=>mutate(()=>{state.title=e.target.value.trim()||'Ein neues Abenteuer';state.demo=false;});$('#next-turn').onclick=()=>mutate(()=>{state.started=true;advance(state);});$('#undo').onclick=()=>{if(!history.length)return;state=history.pop();persist();render();toast('Letzte Änderung zurückgenommen.');};$('#roll-all').onclick=()=>{if(!confirm('Initiative für alle neu würfeln und die Zugfolge in Runde 1 neu starten?'))return;mutate(()=>{for(let p of state.people)p.init=1+Math.floor(Math.random()*20);state.active=order(state.people)[0]?.id??null;state.round=1;});};$('#new-encounter').onclick=()=>{if(!confirm('Neuen, leeren Kampf beginnen? Den aktuellen Kampf kannst du vorher über „Sichern“ herunterladen.'))return;mutate(()=>state={version:1,title:'Ein neues Abenteuer',demo:false,started:false,round:1,active:null,people:[],shapes:[]});toast('Neuer Kampf. Der vorherige lässt sich mit „Rückgängig“ wiederherstellen.');};$('#clear-map').onclick=()=>{if(!state.shapes.length)return;if(confirm('Alle gezeichneten Formen entfernen? Die Figuren bleiben stehen.'))mutate(()=>state.shapes=[]);};
const descriptions={select:'Figuren greifen und auf dem Feld verschieben.',smart:'Frei zeichnen: Linien werden glatt, geschlossene Formen werden Räume.',wall:'Ziehen, um eine gerade Wand zu zeichnen.',rect:'Ziehen, um einen rechteckigen Raum aufzuspannen.',ellipse:'Ziehen, um einen runden Raum aufzuspannen.',erase:'Eine Wand oder einen Raum anklicken, um die Form zu entfernen.'};const names={select:'Verschieben',smart:'Freihand schönziehen',wall:'Wand',rect:'Rechteckiger Raum',ellipse:'Runder Raum',erase:'Form entfernen'};
function setTool(t){tool=t;document.querySelectorAll('[data-tool]').forEach(b=>{b.classList.toggle('selected',b.dataset.tool===t);b.setAttribute('aria-pressed',String(b.dataset.tool===t));});$('#tool-description').textContent=descriptions[t];$('#map-hint').textContent=names[t]+' · '+(t==='smart'?'Kreis oder Rechteck schließen, um einen Raum zu erstellen.':t==='select'?'Tipp: Figuren auch mit Pfeiltasten bewegen.':'Maus oder Finger verwenden.');$('#map').style.cursor=t==='select'?'default':t==='erase'?'crosshair':'crosshair';renderMap();}
document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>setTool(b.dataset.tool));$('#snap').onchange=e=>snap=e.target.checked;
function position(e){const pt=$('#map').createSVGPoint();pt.x=e.clientX;pt.y=e.clientY;const p=pt.matrixTransform($('#map').getScreenCTM().inverse());return{x:clamp(p.x,0,1000),y:clamp(p.y,0,700)};}
const gridPoint=p=>({x:clamp(snap?Math.round(p.x/50)*50:p.x,0,1000),y:clamp(snap?Math.round(p.y/50)*50:p.y,0,700)});
function dragShape(a,b){a=gridPoint(a);b=gridPoint(b);if(tool==='wall')return{type:'wall',points:[a,b]};return{type:tool,x:Math.min(a.x,b.x),y:Math.min(a.y,b.y),w:Math.abs(b.x-a.x),h:Math.abs(b.y-a.y)};}
$('#map').onpointerdown=e=>{if(e.button!==0)return;const pos=position(e),token=e.target.closest('[data-token]'),shape=e.target.closest('[data-shape]');if(tool==='erase'){if(shape)mutate(()=>state.shapes=state.shapes.filter(s=>s.id!==shape.dataset.shape));return;}if(tool==='select'&&!token)return;if(tool!=='select'&&state.shapes.length>=1000){toast('Maximal 1000 Formen. Bitte einige entfernen.');return;}$('#map').setPointerCapture(e.pointerId);if(tool==='select'){const p=state.people.find(p=>p.id===token.dataset.token);gesture={type:'token',id:p.id,start:pos,origin:{x:p.x,y:p.y},before:structuredClone(state)};}else gesture={type:'draw',points:[pos],start:pos};};
$('#map').onpointermove=e=>{if(!gesture)return;let pos=position(e);if(gesture.type==='token'){const p=state.people.find(p=>p.id===gesture.id);let x=gesture.origin.x+pos.x-gesture.start.x,y=gesture.origin.y+pos.y-gesture.start.y;if(snap){x=Math.round((x-25)/50)*50+25;y=Math.round((y-25)/50)*50+25;}p.x=clamp(x,25,975);p.y=clamp(y,25,675);renderMap();}else{if(Math.hypot(pos.x-gesture.points.at(-1).x,pos.y-gesture.points.at(-1).y)>2&&gesture.points.length<2000)gesture.points.push(pos);let draft=tool==='smart'?{type:'path',points:gesture.points}:dragShape(gesture.start,pos);$('#draft').replaceChildren(makeShape(draft,true));}};
function finishGesture(e,cancel=false){if(!gesture)return;const g=gesture;gesture=null;$('#draft').replaceChildren();if(g.type==='token'){if(cancel){state=g.before;render();return;}const p=state.people.find(p=>p.id===g.id);if(p.x!==g.origin.x||p.y!==g.origin.y){history.push(g.before);if(history.length>60)history.shift();persist();render();}return;}if(cancel)return;let sh=tool==='smart'?recognize(g.points,snap):dragShape(g.start,position(e));if(!sh)return;if(sh.points&&(!sh.points.length||Math.hypot(sh.points[0].x-sh.points.at(-1).x,sh.points[0].y-sh.points.at(-1).y)<8&&sh.points.length<=2))return;if(!sh.points&&(sh.w<10||sh.h<10))return;sh.id=uid();mutate(()=>state.shapes.push(sh));if(tool==='smart')toast(sh.type==='rect'?'Rechteck erkannt und ausgerichtet.':sh.type==='ellipse'?'Runder Raum erkannt.':'Linie geglättet und ausgerichtet.');}
$('#map').onpointerup=e=>finishGesture(e);$('#map').onpointercancel=e=>finishGesture(e,true);$('#map').onkeydown=e=>{const token=e.target.closest('[data-token]');if(!token||!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown'].includes(e.key))return;e.preventDefault();const id=token.dataset.token;mutate(()=>{const p=state.people.find(p=>p.id===id),step=snap?50:10;p.x=clamp(p.x+(e.key==='ArrowLeft'?-step:e.key==='ArrowRight'?step:0),25,975);p.y=clamp(p.y+(e.key==='ArrowUp'?-step:e.key==='ArrowDown'?step:0),25,675);});[...$('#tokens').children].find(el=>el.dataset.token===id)?.focus();};
$('#export').onclick=()=>{const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=(state.title.replace(/[^\p{L}\p{N}_-]/gu,'-')||'kampf')+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Kampf inklusive Kampffeld gesichert.');};$('#import').onclick=()=>$('#import-file').click();$('#import-file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>2e6)throw Error();const data=JSON.parse(await f.text());if(!validState(data))throw Error();if(confirm('Gesicherten Kampf laden und den aktuellen ersetzen?')){mutate(()=>state=data);toast('Kampf geladen.');}}catch{toast('Diese Datei ist keine gültige Initiative-Kampfsicherung.');}e.target.value='';};
function info(title,html){$('#info-title').textContent=title;$('#info-content').innerHTML=html;$('#info-dialog').showModal();}$('#help').onclick=()=>info('In einer Minute kampfbereit','<p><b>1. Beteiligte ergänzen.</b> Über ＋ Namen, maximale HP und Initiative eintragen. Mehrere gleiche Gegner kannst du auf einmal hinzufügen.</p><p><b>2. Kampf leiten.</b> Die höchste Initiative steht oben. − verursacht Schaden, ＋ heilt um den Betrag dazwischen. „Nächster Zug“ geht weiter; nach dem letzten Beteiligten beginnt die nächste Runde. Figuren mit 0 HP bleiben in der Zugfolge.</p><p><b>3. Kampffeld zeichnen.</b> ✧ glättet Freihandlinien und erkennt grob geschlossene Rechtecke oder Ovale. Mit ▢ und ◯ zeichnest du Räume direkt. ↖ verschiebt Figuren, ⌫ entfernt Formen.</p><p><b>Kürzel:</b> V Verschieben · F Freihand · W Wand · R Raum · O Oval · E Entfernen. Strg/⌘ + Z macht die letzte Änderung rückgängig.</p><p>Gleiche Initiative bleibt in Einfügereihenfolge. Über ··· kannst du Werte bearbeiten. „Sichern“ lädt den ganzen Kampf als Datei herunter.</p>');$('#privacy').onclick=()=>info('Dein Kampf, dein Browser','<p>Dein Kampf und das Kampffeld werden automatisch <b>nur in diesem Browser</b> gespeichert. Es gibt keine Synchronisation zwischen Geräten oder Spielern.</p><p>Wenn du Browserdaten löschst oder privat surfst, können die Daten verloren gehen. Mit <b>Sichern</b> lädst du eine Datei herunter und kannst sie später mit <b>Laden</b> wieder öffnen.</p>');document.querySelectorAll('.close-dialog').forEach(b=>b.onclick=()=>b.closest('dialog').close());document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target!==d)return;const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}));document.addEventListener('keydown',e=>{if(document.querySelector('dialog[open]')||e.target.matches('input,textarea,select'))return;if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='z'){e.preventDefault();$('#undo').click();return;}if(e.ctrlKey||e.metaKey||e.altKey)return;const t={v:'select',f:'smart',w:'wall',r:'rect',o:'ellipse',e:'erase'}[e.key.toLowerCase()];if(t)setTool(t);});$('.brand').onclick=e=>{e.preventDefault();window.scrollTo({top:0,behavior:'smooth'});};render();setTool('select');if(storageBroken)toast('Gespeicherter Stand konnte nicht geladen werden. Beispiel geöffnet.');
